 "content": "from collections import Counter, deque


def transform(grid):
    """Stamp the largest non-background template around every isolated marker."""
    h, w = len(grid), len(grid[0])
    counts = Counter(v for row in grid for v in row)
    bg = counts.most_common(1)[0][0]
    seen = set()
    comps = []
    for r in range(h):
        for c in range(w):
            if grid[r][c] == bg or (r, c) in seen:
                continue
            q = deque([(r, c)])
            seen.add((r, c))
            comp = []
            while q:
                y, x = q.popleft()
                comp.append((y, x))
                for yy, xx in ((y-1,x),(y+1,x),(y,x-1),(y,x+1)):
                    if 0 <= yy < h and 0 <= xx < w and grid[yy][xx] != bg and (yy,xx) not in seen:
                        seen.add((yy,xx))
                        q.append((yy,xx))
            comps.append(comp)
    if not comps:
        return [row[:] for row in grid]
    motif = max(comps, key=len)
    if len(motif) < 2:
        return [row[:] for row in grid]
    r0 = min(r for r, c in motif)
    r1 = max(r for r, c in motif)
    c0 = min(c for r, c in motif)
    c1 = max(c for r, c in motif)
    ar, ac = (r0 + r1) // 2, (c0 + c1) // 2
    pattern = [(r-ar, c-ac, grid[r][c]) for r, c in motif]
    markers = [comp[0] for comp in comps if len(comp) == 1 and comp is not motif]
    out = [row[:] for row in grid]
    for mr, mc in markers:
        for dr, dc, color in pattern:
            rr, cc = mr + dr, mc + dc
            if 0 <= rr < h and 0 <= cc < w:
                out[rr][cc] = color
    return out


if __name__ == '__main__':
    import json, sys
    print(json.dumps(transform(json.load(sys.stdin))))
